window.MONSTER_CHUNK_117 = [{"name":"Decapus","cr":3,"xp":800,"alignment":"CE","size":"Medium","type":"aberration","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+1 Dex, +4 natural","hp":26,"hd":"4d8+8","hdvalue":4,"fort":3,"ref":2,"will":4,"speed":[{"type":"land","speed":10},{"type":"climb","speed":30}],"melee":"9 tentacles +6 (1d4+2 plus grab)","space":"5 ft.","reach":"5 ft. (10 ft. with tentacles)","special_attacks":[{"type":"constrict","details":"1d4+2 Spell-like ability (CL 5th) At will-minor image (DC 13)"}],"strength":14,"dexterity":13,"constitution":15,"intelligence":10,"wisdom":11,"charisma":12,"baseatk":3,"cmb":5,"cmb_special":"+4 vs. grapple","cmd":16,"cmd_special":"+16 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Climb","value":15},{"skill":"Perception","value":9},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":8},{"skill":"Survival","value":7}],"languages":["Decapus"],"sq":[{"type":"brachiation"},{"type":"sound imitation"}],"environments":["temperate forests","temperate underground"],"organizations":["solitary (or rarely, a mated pair)"],"treasure":"standard","description_visual":"This creature is a large spheroid with ten octopus-like tentacles protruding from its body. Hair grows in broken patches along its body.  Its eyes are stark white and pupil-less. Its large mouth sports long, yellow fangs.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Brachiation","kind":"Ex","details":"A decapus can move through trees at its base climb speed (30 ft. per round) by using its tentacles to swing from tree to tree. Trees used by the decapus in this manner can be no further than 10 ft. apart."},{"type":"Sound Imitation","kind":"Ex","details":"A decapus can mimic any creature it has previously encountered with near total accuracy, though it cannot mimic humanoid speech longer than two or three words at a time. A DC 13 Will save detects the ruse. The save DC is Charisma-based."}],"description":"Decapi are solitary creatures that dwell in dense forests or underground.\n\nMost prefer the forests as their ability to move among the trees allows them to either pursue their prey or flee in situations not to their advantage.\n\nOn the ground, decapi are slow-moving, thus they spend most of their time among the tree tops.\n\nDecapi are nocturnal hunters and are quite fond of human, elf, and halfling flesh. In times when food is scarce, they exist on a diet of rats, snakes, and other small forest creatures (or dungeon denizens in the case of the subterranean decapus).\n\nDecapi prefer a solitary life; the only time more than one will ever be encountered together is during mating season (usually the fall). Young decapi are born live, and the female only ever gives birth to a single young during each mating season. If food is extremely scarce, some decapus females have been known to eat their young.\n\nThis creature's body is a 4-foot diameter globe of pallid green. On rare occasions, a purple or even yellow hued decapus may be encountered.\n\nPatches of dark hair, brown or black, grow in various locations. Regardless of its body color, each decapus has 10 octopus-like tentacles protruding from its spherical body. Each tentacle is covered in suction cups that aid the creature in not only climbing and moving through trees, but also in holding on to its prey. Its large wide maw sports sickly yellow teeth and foul breath.\n\nDecapi seem to be able to speak with others of their kind using a series of guttural noises.","ecology":"","habitat_society":"","credit":"The Decapus originally appeared in the First Edition module B3 Palace of the Silver Princess (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Defender Globe","cr":3,"xp":800,"alignment":"N","size":"Small","type":"outsider","subtypes":["elemental","native"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":17,"ac_flat_footed":13,"ac_mods":"+2 deflection, +3 Dex, +1 dodge, +1 size","hp":26,"hd":"4d10+4","hdvalue":4,"fort":2,"ref":7,"will":5,"defensive_abilities":["awareness","defensive aura"],"immunities":["electricity"],"resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":5},{"type":"fly","speed":40,"maneuverability":"perfect"}],"ranged":"electrical bolt +8 (2d6 electricity)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"light"}]}],"strength":4,"dexterity":16,"constitution":12,"intelligence":4,"wisdom":12,"charisma":14,"baseatk":4,"cmb":10,"cmd":21,"feats":[{"feat":"Dodge"},{"feat":"Mobility"}],"skills":[{"skill":"Fly","value":20},{"skill":"Knowledge (planes)","value":4},{"skill":"Perception","value":8}],"environments":["any"],"organizations":["solitary"],"treasure":"incidental","description_visual":"This small glowing orb radiates light similar to that of a lantern. Small filaments of electrical energy dance across its illuminated surface.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Awareness","kind":"Ex","details":"A defender globe cannot be surprised or flanked."},{"type":"Defensive Aura","kind":"Ex","details":"A defender globe adds its Charisma bonus to its AC and CMD as a deflection bonus."},{"type":"Flight","kind":"Su","details":"A defender globe can cease or resume flight as a free action. The ability is supernatural, so it becomes ineffective in an antimagic field, and the defender globe loses its ability to fly for as long as the antimagic effect persists."}],"description":"This small outsider is bound by spellcasters using the summon monster III or lesser planar binding spells, serving for up to 1 day per caster level. Using more powerful incantations can bind the globes for longer periods (GM's discretion).\n\nThey can understand, but not speak, any language spoken by their summoner. The summoned globes can understand simple orders, and carries out their last order until destroyed or dismissed.","ecology":"","habitat_society":"","credit":"Originally appearing in Rappan Athuk (© Frog God Games, 2012)"},{"name":"Dire Mastiff","cr":3,"xp":800,"alignment":"N","size":"Large","type":"animal","init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+2 Dex, +4 natural, -1 size","hp":42,"hd":"5d8+20","hdvalue":5,"fort":8,"ref":6,"will":3,"speed":[{"type":"land","speed":50}],"melee":"bite +7 (1d8+6 plus trip)","space":"10 ft.","reach":"5 ft.","strength":19,"dexterity":15,"constitution":18,"intelligence":2,"wisdom":12,"charisma":10,"baseatk":3,"cmb":1,"cmd":14,"cmd_special":"+4 vs. trip","feats":[{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Acrobatics","value":7,"special":"+11 jumping"},{"skill":"Perception","value":9},{"skill":"Survival","value":2,"special":"+6 scent tracking"}],"environments":["any"],"organizations":["solitary","pair","pack (3-12)"],"treasure":"none","description_visual":"This large black hound is about the size of a small horse.","source":"Tome of Horrors 4 (3pp)","description":"Dire mastiffs are the domestic equivalent of dire wolves. They are large, vicious canines highly prized for their ability to track and kill opponents much larger than themselves. Domesticated dire mastiffs are often trained and outfitted for war in spiked, studded leather armor. Orcs often use trained dire mastiffs in warfare.\n\nDire mastiffs are much like wolves, and in the wild, they commingle in packs of up to twelve. The dominant male is always the leader, though other males frequently challenge for the position. Such exchanges, while violent, rarely result in death. The loser of the contest simply submits to the victor and acknowledges it as the new pack leader.\n\nDire mastiffs are carnivores and their diet consists of just about any animal or creature they can catch and kill. Favorite meals include leopards, skunks, horses, and rodents. They rarely devour humanoid flesh, but will do so if food is scarce. Kills are often carried back to the lair and distributed among the pups and females.\n\nDire mastiffs breed twice a year, usually every 6 months. The actual month or time varies depending on climate, terrain, and other environmental factors. Gestation lasts about 4 months after which time the female gives birth to 1d3+3 pups. Pups depend on their mother or the hunters of a pack to feed them and rarely journey out on their own until they reach 4 months of age. Dire mastiffs reach maturity around 8 months after birth.\n\nBefore attacking, the hair on the neck of a dire mastiff rises, its ears fold back, its tail stiffens, and it bears its sharpened teeth, through which a low growl is often heard. A dire mastiff rushes its opponent and bites ferociously with its powerful jaws.","ecology":"","habitat_society":""},{"name":"Dire Stag","cr":3,"xp":800,"alignment":"N","size":"Large","type":"animal","init":3,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+3 Dex, +1 dodge, +4 natural, -1 size","hp":42,"hd":"5d8+20","hdvalue":5,"fort":8,"ref":9,"will":5,"speed":[{"type":"land","speed":40}],"melee":"gore +7 (1d8+5), 2 hooves +5 (1d6+2)","space":"10 ft.","reach":"5 ft.","strength":21,"dexterity":17,"constitution":18,"intelligence":2,"wisdom":15,"charisma":10,"baseatk":3,"cmb":19,"cmb_special":"+4 vs. grapple","cmd":31,"cmd_special":"+4 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack","type":"bonus"},{"feat":"Run"}],"skills":[{"skill":"Perception","value":12},{"skill":"Stealth","value":8}],"environments":["cold forests","cold plains","temperate forests","temperate plains"],"organizations":["solitary","pair","herd (10-50 deer plus 1 dire stag per 10 deer)"],"treasure":"none","description_visual":"This gigantic stag stands as tall as a human at the shoulders and has antlers that are almost twice that long.","source":"Tome of Horrors 4 (3pp)","description":"Dire stags are impressive creatures found in all but the warmest regions. Most inhabit forests and plains, though some often roam more rugged territory. Dire stags are aggressive giant versions of male deer.\n\nDire stag are nocturnal creatures and exist on a diet of leaves, vines, ivy, and meat, the latter consisting of rodents and small animals (rabbits, moles, pigs, and wolves). A typical male's territory covers a range of 5 square miles. Dire stags mark territorial boundaries by digging holes with their antlers. Such holes can measure up to 6 ft. wide and 3 ft. deep. They often thrash the ground throughout their territory, stirring up the leaves and underbrush, to further define their territory.\n\nDire stags are solitary creatures, but sometimes band together, usually during mating or rutting season. During rutting season, a dire stag gathers up to 12 female deer in its territory. Mating season is usually late fall and gestation typically lasts 8 months. Newborn are nursed by the females and are dependent on their mother for the first few months of their lives. Young are slowly weaned over a period of 6 months and reach maturity by 18 months.\n\nA dire stag stands 6 ft. at the shoulder and about 12 ft. long with its weight exceeding 1,000 pounds. Its antlers average up to 8 ft. wide, though some of the largest dire stag have antlers reaching up to 12 ft. wide. Its coat varies in color from brown to brownish-white to black, with its underbelly being lighter, and usually white. Its antlers are brown or black. Dire stags are hunted for their meat as well as their tough hides. A reasonably intact dire stag hide is worth 500 gp or more.\n\nDire stags are aggressive animals and rarely back down from a challenge. They unleash a guttural, blood-curdling bleat before attacking. This serves to warn the females and young as well as potential aggressors. Dire stags almost never retreat, preferring to fight to the death against a foe.\n\nA dire stag attacks with its antlers, goring its opponent, or it rears onto its hind legs and slashes with its hooves. Most dire stags fight to the death to protect their young.","ecology":"","habitat_society":""},{"name":"Disenchanter","cr":3,"xp":800,"alignment":"N","size":"Large","type":"magical beast","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+3 Dex, +3 natural, -1 size","hp":37,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":7,"will":5,"dr":"5/magic","speed":[{"type":"land","speed":30}],"melee":"snout +7 touch (disenchantment) or 2 hooves +6  (1d6+3)","space":"10 ft.","reach":"5 ft.","spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect magic"}]}],"strength":16,"dexterity":16,"constitution":14,"intelligence":2,"wisdom":11,"charisma":4,"baseatk":4,"cmb":10,"cmd":21,"cmd_special":"can't be tripped","feats":[{"feat":"Iron Will"},{"feat":"Weapon Focus (snout)"}],"skills":[{"skill":"Perception","value":7}],"environments":["any"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This creature resembles a massive blue furred camel with slightly translucent skin and a long snout that ends in a suction-like cup.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Disenchantment","kind":"Ex","details":"A disenchanter that makes a successful touch attack with its snout drains one magic item carried or worn by the target (determined randomly by the DM). If the disenchanter aims at a particular item, it must make an attack roll against that item's AC. Items worn or carried have an AC equal to 10 + its size modifier + the opponent's Dexterity modifier (if any). A disenchanter doesn't provoke attacks of opportunity when using this ability. An item struck must succeed on a DC 14 Fortitude save or permanently lose all magical properties it possesses. An unattended magic item has a save bonus equal to 2 + one-half its caster level. An attended magic item either makes its save as its owner or uses its own saving throw whichever is better. The save DC is Constitution-based. Disenchanters cannot affect artifacts."}],"description":"The disenchanter is greatly feared for the damage it can cause. Much like a rust monster, it feeds on objects most adventurers hold near and dear to their hearts-magic items. A typical disenchanter is about 8 ft. long and weighs 600 pounds.\n\nA disenchanter targets magical items carried or worn by an opponent. A disenchanter is able to discern the most powerful magical items in a group and always attack those items first, unless those items are too difficult to reach (such as hidden in a backpack), in which case the disenchanter will choose to attack a more readily available item (such as a magical shield). It fastens its snout onto an item and drains the item's magical properties. Magical weapons striking a disenchanter cannot be drained of their magical properties.\n\nA disenchanter's natural weapons are treated as magic weapons for the purpose of overcoming damage reduction.","ecology":"","habitat_society":"","credit":"The Disenchanter originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Eblis","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"magical beast","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+3 Dex, +1 dodge, +4 natural","hp":26,"hd":"4d10+4","hdvalue":4,"fort":5,"ref":9,"will":2,"resists":[{"type":"fire","value":5}],"speed":[{"type":"land","speed":30},{"type":"fly","speed":30,"maneuverability":"average"}],"melee":"beak +5 (1d6+1)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"blur"},{"spell":"disguise self"},{"spell":"fog cloud"},{"spell":"ghost sound"},{"spell":"hypnotic pattern"},{"spell":"hypnotism"},{"spell":"scare"},{"spell":"whispering wind"}]}],"strength":12,"dexterity":16,"constitution":13,"intelligence":12,"wisdom":12,"charisma":12,"baseatk":4,"cmb":5,"cmd":19,"feats":[{"feat":"Dodge"},{"feat":"Lightning Reflexes"},{"feat":"Mobility","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":8},{"skill":"Diplomacy","value":3},{"skill":"Fly","value":8},{"skill":"Intimidate","value":3},{"skill":"Perception","value":6},{"skill":"Stealth","value":8}],"languages":["Common","Eblis"],"environments":["temperate marshes"],"organizations":["flock (4-16)"],"treasure":"standard","description_visual":"This creature appears to be about 8 ft. tall and strongly resembles a stork. Its feathers are gray-brown and its beak is dark brown. Its eyes are golden in color.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Spell-Like Abilities","kind":"Sp","details":"Each eblis flock has one individual capable of using arcane magic. A spellcasting eblis has 2d4 spells, each spell usable once per day. Each spell is caster level 4th and has a save DC of 11 + the level of the spell. Eblis spells require no material or verbal components; only somatic, which consists of dancing and vocalizations. The save DCs are Charisma-based. Choose or randomly determine (using the table below) the eblis's spells. 1d8 Spell 1 ghost sound 2 disguise self 3 hypnotism 4 scare 5 fog cloud 6 blur 7 hypnotic pattern 8 whispering wind."}],"description":"The eblis are a semi-civilized society of birdmen that make their homes in desolate swamps and marshes. They rarely have interactions with other races, preferring the company of their own kind and the serenity of their marshland homes. An eblis is a large bird that strongly resembles a stork - so much so that eblis are often called \"stork men.\" An eblis stands about 8 ft. tall, and the neck is extremely long and snake-like and is unnaturally flexible and capable of blindingly fast movements. An eblis' beak is long, sharp, and deadly. A male eblis has gray-brown feathers with reddish patches on its head, while a female lacks the red patch. Storkmen are very fast at shifting and striking, and their necks are very powerful despite their slenderness. They attack by stabbing with their beak.","ecology":"","habitat_society":"","credit":"The Eblis originally appeared in the First Edition module EX2 Land Beyond the Magic Mirror (© TSR/Wizards of the Coast, 1983) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Elusa Hound","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"magical beast","init":2,"senses":[{"type":"arcane sight"},{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 Dex, +3 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":6,"will":2,"sr":12,"speed":[{"type":"land","speed":50}],"melee":"bite +6 (1d6+3 plus trip)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":15,"constitution":15,"intelligence":6,"wisdom":12,"charisma":8,"baseatk":4,"cmb":6,"cmd":18,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Survival)"}],"skills":[{"skill":"Perception","value":8},{"skill":"Survival","value":10,"special":"+14 tracking by scent"}],"languages":["understands Common (but cannot speak)"],"sq":[{"type":"aura tracking"}],"environments":["temperate forests","temperate plains"],"organizations":["solitary","pair","pack (4-7)"],"treasure":"none","description_visual":"This powerful wolf-like dog has coarse white fur and pale white skin, and a short, bushy tail. Its eyes are a sickly yellow in color and its teeth are bone white.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Arcane Sight","kind":"Su","details":"Elusa hounds can detect magical auras in a 120-foot radius, as per the arcane sight spell cast by a sorcerer at 6th level. This ability can be dispelled, but the elusa hound can restart it as a free action on its next turn. Using this ability, the elusa hound can instantly identify any spellcaster within range."},{"type":"Aura Tracking","kind":"Su","details":"If an elusa hound has \"tasted\" the magical aura of a living creature (a creature it has successfully used its arcane sight ability against or a spell it has successfully detected that was cast by such a creature), it gains a +10 competence bonus to its Survival check when tracking that target. The aura must be fresh (\"tasted\" within the last 3 hours) or the elusa hound doesn't gain this bonus."}],"description":"Elusa hounds are used by different creatures for different reasons; though ultimately there have but one purpose: tracking (and often killing) magic-wielders. These creatures can detect the emanations given off by arcane and divine spellcasters and use this scent to track them. The origins of the elusa hounds have mystified even the most learned of sages, for though they seem to be born of magic, no spellcaster in his or her right mind would ever create such a beast.\n\nRenegade bands enthralled with the idea of ridding the world of spellcasters sometimes employ them. Civilized towns and cities likewise use them in places where magic is forbidden or policed by the local government. In other instances, they are used by spellcasters to ferret out rivals.\n\nWhen given instructions to track and kill their target, a pack of elusa hounds uses tactics similar to other canine animals: circle the prey and attack simultaneously from the front, rear, and flanks. These beasts can easily be trained to pin or hold a foe rather than kill it. This tactic is often employed by military or government units when they wish to capture and interrogate a renegade spellcaster. When using these tactics, the elusa hound attempts to trip its foe and then pins it with a bite.\n\nElusa hounds radiate a moderate aura of divination magic if examined with detect magic or the like.","ecology":"","habitat_society":""},{"name":"Fire Drake","cr":3,"xp":800,"alignment":"CE","size":"Small","type":"dragon","subtypes":["fire"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":15,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+1 Dex, +3 natural, +1 size","hp":30,"hd":"4d12+4","hdvalue":4,"fort":5,"ref":5,"will":4,"defensive_abilities":["pyrophoric blood (DC 13, 1d3 fire)"],"immunities":["fire","paralysis","sleep"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"bite +7 (1d6+1), 2 claws +6 (1d4+1)","space":"5 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"20 ft. cone, DC 13, 2d8 fire"}],"strength":13,"dexterity":13,"constitution":13,"intelligence":4,"wisdom":11,"charisma":10,"baseatk":4,"cmb":4,"cmd":15,"cmd_special":"+4 vs. trip","feats":[{"feat":"Flyby Attack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Fly","value":10},{"skill":"Perception","value":7},{"skill":"Stealth","value":12}],"languages":["Draconic"],"environments":["temperate hills"],"organizations":["pair","clutch (2-5)","family (6-8)"],"treasure":"standard","description_visual":"This creature appears to be a small, red dragon with translucent scales, mottled mauve and burgundy. Heat and steam rise from its body. Its wings are mottled black and its eyes are crimson.","group":"Drake","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A fire drake's breath weapon is a 20 ft. cone of fire."},{"type":"Pyrophoric Blood","kind":"Ex","details":"A fire drake's blood is highly flammable and ignites in a burst of flame upon contact with the air. A creature that makes a successful attack with a slashing or piercing weapon (including natural weapons) against a fire drake must succeed on a Reflex save or take 1d3 points of fire damage from the splashing blood."}],"description":"Fire Drake Blood The blood of a fire drake can be sealed in an airtight container and used as a firebomb, equivalent to a flask of alchemist's fire. It can also be used to create temporary flaming weapons.\n\nA weapon coated with fire drake's blood acts as a flaming weapon for 1d4 rounds or until the first successful hit, whichever comes first.\n\nFire drakes lair in caves and caverns deep within the hills and mountains.\n\nFire drakes are carnivorous creatures and very territorial, fighting other drakes that move into their area. They are tolerant of other fire drakes, but view them with suspicion. On occasion, a mated pair is encountered, but only in the late summer months or early autumn.\n\nFire drakes are often mistaken for young or miniature red dragons. A typical fire drake is 4 ft. long, though it can grow to a length of 6 ft.\n\nFire drakes prefer to open combat with their breath weapon. Once expended, they rely on their bite. Their claws are too small to be effective in combat.","ecology":"","habitat_society":"","credit":"The Fire Drake originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Flail Snail","cr":3,"xp":800,"alignment":"N","size":"Large","type":"magical beast","init":-1,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"scent"},{"type":"tremorsense","modifier":"60 ft."}],"ac":18,"ac_touch":8,"ac_flat_footed":18,"ac_mods":"-1 Dex, +10 natural, -1 size","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":3,"will":2,"defensive_abilities":["warp magic"],"immunities":["poison"],"resists":[{"type":"fire","value":20}],"speed":[{"type":"land","speed":10},{"type":"climb","speed":10}],"melee":"4 slams +7 (1d6+3)","space":"10 ft.","reach":"5 ft. (10 ft. with tentacles)","special_attacks":[{"type":"mucus"}],"strength":16,"dexterity":8,"constitution":14,"intelligence":5,"wisdom":12,"charisma":8,"baseatk":4,"cmb":8,"cmd":17,"cmd_special":"can't be tripped","feats":[{"feat":"Power Attack"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Climb","value":15},{"skill":"Perception","value":6},{"skill":"Stealth","value":-1}],"languages":["Flail Snail (sign language and slime writing, cannot speak)"],"sq":[{"type":"mucus"},{"type":"retraction"},{"type":"slime rope"},{"type":"suction"},{"type":"warp magic"}],"environments":["any underground"],"organizations":["solitary","pair","rout (3-30)"],"treasure":"shell worth 800 gp","description_visual":"This creature looks like a large massive version of a normal snail whose head has been replaced with four man-sized tentacles, each ending in a mace-like ball. Its shell is striped in bright colors of red, blue, yellow, and green. Its flesh is gray-blue.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Mucus","kind":"Ex","details":"As a free action, a flail snail can excrete a trail of mucus which covers its space and lasts for 10 minutes. This mucus comes in two types: slimy and sticky. Slimy mucus covers three squares with the effects of a grease spell. Sticky mucus covers the squares with the effects of a web spell. Both effects are DC 14. The saves are Constitution-based. Flail snails are immune to this mucus. Both types of mucus can be burned way as per the web spell."},{"type":"Retraction","kind":"Ex","details":"A flail snail can pull its fleshy parts back into its shell as a swift action, increasing its natural armor bonus by +6, but it cannot move or attack while retracted. It can return to normal as a free action."},{"type":"Slime Rope","kind":"Ex","details":"A flail snail can turn its mucus into a ropelike strand up to 60 ft. long, and can use this rope to hang itself and up to 1,000 extra pounds from the ceiling indefinitely, or to lower itself safely at a speed of 20 ft. per round. It can climb back up this rope at a speed of 10 ft. per round. Once the snail breaks contact with the rope, the slime decomposes in 1d4 rounds, after which it cannot be used by the snail or any other creatures. While the slime rope exists, other creatures can climb the rope with a DC 20 Climb check."},{"type":"Suction","kind":"Ex","details":"A snail's foot adheres to surfaces so well that its 10-foot climb speed applies even on perfectly sheer surfaces and ceilings, with no chance to fall off unless the foot is actively pinned and peeled away as part of a grapple."},{"type":"Warp Magic","kind":"Su","details":"Anytime a spell targets a flail snail, there is an 80% chance that it produces a random effect instead of affecting the snail. Only spells that directly target the flail snail are warped; area effect spells are not affected. If a spell is warped, roll 1d10 and consult the following table. 1d10 Result 1-3 Spell misfires. For the next 1d4 rounds, the caster must make a DC 15 concentration check to successfully cast spells. 4-6 Spell misfires. The creature nearest the flail snail is affected as if the spell had been cast on him. 7-9 Spell fails; nothing happens 10 Spell rebounds on caster (as spell turning)"}],"description":"Flail snails are solitary omnivores found in the deepest recesses of caverns, caves, and dungeons. There they sustain themselves on a diet of fungus, mold, and rodents. The shell of a dead flail snail can be sold on the open market for 3,000-5,000 gp. A flail snail attacks by smashing its prey with its mace-like tentacles. It attacks until either it or its opponents are dead. Greater Flail Snail A flail snail has one mace-like tentacle per Hit Die. Thus, a 6 HD flail snail has 6 tentacles; an 8 HD flail snail has 8 tentacles; and a 12 HD flail snail has 12 tentacles.","ecology":"","habitat_society":"","credit":"The Flail Snail originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Frost Drakeling","cr":3,"xp":800,"alignment":"N","size":"Tiny","type":"dragon","subtypes":["cold"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+3 Dex, +2 natural, +2 size","hp":25,"hd":"3d12+6","hdvalue":3,"fort":5,"ref":6,"will":4,"immunities":["cold","paralysis","sleep"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":20},{"type":"fly","speed":40,"maneuverability":"poor"}],"melee":"bite +8 (1d6-1 plus 1d4 cold)","space":"1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"icy breath"},{"type":"cold generation"}],"strength":8,"dexterity":17,"constitution":14,"intelligence":6,"wisdom":13,"charisma":8,"baseatk":3,"cmb":4,"cmd":13,"feats":[{"feat":"Flyby Attack"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":4},{"skill":"Fly","value":8},{"skill":"Intimidate","value":4},{"skill":"Perception","value":7},{"skill":"Stealth","value":17}],"languages":["Draconic"],"sq":[{"type":"icewalking"}],"environments":["cold hills","cold mountains"],"organizations":["solitary","band (2-4)"],"treasure":"standard","description_visual":"This miniature dragon has dull blue scales and long wings with ice blue tipped claws.","group":"Drakeling","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Cold Generation","kind":"Su","details":"As a free action, a frost drakeling can decrease its body temperature to extreme levels. Creatures attacking the frost drakeling with natural weapons or touching the frost drakeling take 1d4 points of cold damage each round of contact."},{"type":"Icewalking","kind":"Ex","details":"This ability works like spider climb, but the surfaces the frost drakeling climbs must be icy. It can move across icy surfaces without penalty and doesn't need to make Acrobatics checks to run or charge on ice."},{"type":"Icy Breath","kind":"Su","details":"A frost drakeling can, as a standard action, spit a line of freezing ice to a range of 20 ft. A creature struck takes 3d6 points of cold damage (DC 13 Reflex half). Further, a creature that fails its save is slowed (as the slow spell) for 1d4 rounds. Once a frost drakeling uses its icy breath, it cannot use it again for 1d4 rounds. The save DC is Constitution-based."}],"description":"Frost drakelings are, like their counterparts the flame drakelings, believed to be related to or an offshoot of dragons or drakes (in this case white dragons or frost drakes). As with the flame drakelings however, scholars find nothing linking the races together.\n\nFrost drakelings are diurnal hunters and feed upon small game found in their artic territories. Frost drakelings hunts are known to span several miles from their lair, especially if tracking game. Prey is killed and dragged back to their lair (usually a frigid cave complex set into the side of a mountain out of reach of other predators).\n\nFrost drakelings are about 18 inches long and weigh 50 pounds. Their scales are dull blue with some frost drakelings having white blotches on their bodies. Wings are long and thin and usually icy blue in color. Eyes are deep, rich blue in color. Frost drakelings mate for life and when reproducing, the female lays a small clutch of one to three eggs. Eggs are small, frail, and sapphire blue in color, resembling large gemstones. The eggs hatch within 6 months, and young reach maturity within 2 years. Frost drakelings live up to 120 years on average.\n\nFrost drakelings, unlike other drakelings, don't shy away from combat. When confronted, the creature unleashes its frigid breath weapon and swoops in to attack with its bite.","ecology":"","habitat_society":""},{"name":"Fungoid","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"plant","subtypes":["fungus"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+1 Dex, +7 natural","hp":37,"hd":"5d8+15","hdvalue":5,"fort":7,"ref":2,"will":1,"immunities":["plant traits"],"resists":[{"type":"electricity","value":10}],"speed":[{"type":"land","speed":30}],"melee":"2 slams +8 (1d8+4)","space":"5 ft.","reach":"5 ft.","strength":19,"dexterity":12,"constitution":17,"intelligence":4,"wisdom":11,"charisma":6,"baseatk":3,"cmb":7,"cmd":18,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Perception","value":10},{"skill":"Stealth","value":6,"special":"+14 in swampy or forested areas"}],"languages":["Common (understands but cannot speak)"],"environments":["temperate marshes","warm marshes"],"organizations":["gang (2-4)","cluster (6-10)"],"treasure":"none","description_visual":"This tall, stocky and powerful humanoid seems formed of mushroom flesh. Its rough facial features are crudely discernible and its arms end in oversized hands.","source":"Tome of Horrors Complete (3pp)","description":"Fungoids are man-sized humanoid creatures formed of mushroom flesh and leaves. Coloration varies from brownish-green or brown to dark green mottled with brown splotches. Most weigh about 300 pounds.\n\nThey are found in all but the coldest of swamps and marshes and delight in attacking creatures that wander too close to their lair. Fungoids are carnivores and consider the flesh of humans, elves, and goblins a delicacy.\n\nWhen food is scarce, fungoids become scavengers and feed on carrion.\n\nFungoids lair in the darkest and most dismal place they can find-the more devoid of light, the better. Typically a lair is ringed with mushrooms of varying colors, shapes and sizes. Such a telltale sign is often the only clue that a fungoid lair is present as the lair itself is normally well-hidden or camouflaged. Woe to a creature that actually wanders close enough to examine the mushrooms; by then the fungoids are likely aware of the interloper's presence and are biding their time before an all-out-attack.\n\nFungoids are nocturnal hunters and often travel up to 5 miles away from their lair in search of prey. Slain prey is carried or dragged back to the lair and devoured over several days time. Multiple fungoids are often encountered together on hunting excursions, but they never share their kill. \"Each to their own\" is the unspoken motto among fungoids.\n\nFungoids are straightforward combatants that rush into melee swinging their powerful fists. They pummel their foes relentlessly until they are destroyed or their adversaries are killed. Multiple fungoids sometimes work with one another to bring down powerful foes, but once the fight is over, the fungoids cooperation with one another ends, and it's every creature for itself when assessing and gathering up the kills. Fungoids never retreat and always fight to the death.","ecology":"","habitat_society":""},{"name":"Gambado","cr":3,"xp":800,"alignment":"CN","size":"Medium","type":"aberration","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+1 Dex, +3 natural","hp":26,"hd":"4d8+8","hdvalue":4,"fort":3,"ref":2,"will":5,"speed":[{"type":"land","speed":40}],"melee":"bite +5 (1d8+2), 2 claws +5 (1d4+2)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":12,"constitution":14,"intelligence":6,"wisdom":12,"charisma":8,"baseatk":3,"cmb":5,"cmd":16,"feats":[{"feat":"Alertness"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Acrobatics","value":6,"special":"+14 jump"},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":5},{"skill":"Stealth","value":9}],"environments":["temperate plains"],"organizations":["solitary","gang (2-5)"],"treasure":"standard coins or goods; no items","description_visual":"A dull white humanoid skull lies on the ground in a tangle of sticks, leaves, and twigs.","source":"Tome of Horrors Complete (3pp)","description":"A gambado makes its lair in a 6-foot deep pit. It hides its body with rocks, leaves, and anything else in the surrounding area, allowing only its head to be seen. Thus, when viewing a hidden gambado, it appears to be nothing more than a humanoid skull resting on the ground. When living creatures approach the gambado, it strikes.\n\nThe gambado is a human-sized creature with a cylindrical torso topped by a humanoid skull-like head. Two long arms ending in razor-sharp claws protrude from the body. Its torso ends in three long, single-toed ft. Its body is gray in color and leathery and can be compressed like a spring. This is its primary means of locomotion. By compressing its body, the gambado can spring up or forward.\n\nGambado are solitary creatures by nature, and on the rare occasion that more than one is encountered, each will have its own lair and pit from which it attacks. The pits are usually close together to maximize their attacks on creatures within the area. Any treasure collected by a gambado is stored on its pit floor or in a small and well-hidden hole (DC 18 Perception to find) in the side of its pit.\n\nGambados speak no known languages, and it is unknown how they communicate among themselves.\n\nA gambado springs to attack any time a living creature comes within 2 ft. of its lair. It attacks relentlessly with its bite and claws, but doesn't fight to the death. If combat goes against it, it seeks the quickest possible means of escape.","ecology":"","habitat_society":"","credit":"The Gambado originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Ghoul-stirge","cr":3,"xp":800,"alignment":"CE","size":"Medium","type":"undead","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":15,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+3 Dex, +2 natural","hp":22,"hd":"4d8+4","hdvalue":4,"fort":2,"ref":4,"will":6,"immunities":["undead traits"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":50,"maneuverability":"average"}],"melee":"bite +6 (1d6 plus paralysis)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain","details":"1d4 Constitution"},{"type":"paralysis","details":"1d4+1 rounds, DC 13"}],"strength":10,"dexterity":17,"intelligence":6,"wisdom":14,"charisma":12,"baseatk":3,"cmb":3,"cmd":16,"cmd_special":"+12 vs. trip","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":7},{"skill":"Perception","value":11},{"skill":"Stealth","value":10}],"languages":["Common (cannot speak)"],"environments":["any"],"organizations":["solitary","gang (2-4)","flock (5-8)"],"treasure":"none","description_visual":"This human-sized creature looks like a cross between a large bat and a giant mosquito. Its wings are leathery and gray and its skin is drawn tight across its bones. The creature has eight pincer-like legs and a long needle-like snout. Its eyes glow pale blue.","source":"Tome of Horrors Complete (3pp)","description":"A ghoul-stirge resembles a large stirge with rotting flesh and broken wings. The origin of the ghoul-stirge has been lost, but it is believed to be the result of a failed magical experiment conducted in ages past by a group of evil and (thought to be) insane necromancers.\n\nThough they can generally be encountered anywhere, ghoul-stirges seem to favor desolate places such as ruins and caverns or dungeons deep underground. Being undead they don't have to eat, but seem to draw sustenance from the blood of enemies (much like a vampire).\n\nA ghoul-stirge is about 5 ft. long with a wingspan almost twice its length. Ghoul-stirges seem to understand Common, but apparently cannot (or choose not to) speak it.\n\nA ghoul-stirge attacks by swooping down on its opponent and attempting to paralyze it with its bite attack. Opponents that resist its paralysis are attacked again, while paralyzed opponents are drained of their blood at the first opportunity. (A ghoul-stirge won't ignore other foes to drain the blood from a paralyzed enemy.)","ecology":"","habitat_society":"","credit":"The Ghoulstirge originally appeared in the First Edition module L1 The Secret of Bone Hill (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Giant Boring Beetle","cr":3,"xp":800,"alignment":"N","size":"Large","type":"vermin","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":9,"ac_flat_footed":15,"ac_mods":"+6 natural, -1 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":1,"will":1,"defensive_abilities":["hive mind"],"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20}],"melee":"bite +6 (2d6+6)","space":"10 ft.","reach":"5 ft.","strength":18,"dexterity":10,"constitution":16,"wisdom":10,"charisma":9,"baseatk":3,"cmb":8,"cmd":18,"cmd_special":"+8 vs. trip","environments":["temperate forests"],"organizations":["cluster (2-5)","swarm (6--1)","hive (12-19 plus 2-8 shriekers)"],"treasure":"none","description_visual":"This giant beetle has a greenish-gray carapace and wing-covers, and its legs and mandibles are black.","group":"Beetle","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Hive Mind","kind":"Ex","details":"All boring beetles within 1 mile of each other are in constant communication. If one is aware of a particular danger, they all are. If one in the group isn't flatfooted, then none of them are. No boring beetle in a group is considered flanked unless all of them are."}],"description":"Boring beetles feed primarily on wood, mold, fungus, and other organic matter. They make their lairs inside ancient tunnels and caverns, where they harvest and grow molds and fungi. Shriekers are prized for both food and their use as alarms to warn the boring beetles of intrusion. Boring beetles are about 9 ft. long.\n\nBoring beetles bite with their powerful mandibles. Slain victims are dragged to their lair and used to grow new molds and fungi.","ecology":"","habitat_society":"","credit":"The Boring Beetle originally appeared in the First Edition Monster Manual (© TSR/Wizards of the Coast, 1977) and is used by permission."},{"name":"Worker Giant Bumblebee","cr":3,"xp":800,"alignment":"N","size":"Large","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":15,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+2 Dex, +4 natural, -1 size","hp":32,"hd":"5d8+10","hdvalue":5,"fort":6,"ref":3,"will":2,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"sting +6 (1d8+6 plus poison)","space":"10 ft.","reach":"5 ft.","strength":18,"dexterity":14,"constitution":14,"wisdom":13,"charisma":10,"baseatk":3,"cmb":8,"cmd":20,"cmd_special":"(+8 vs. trip","skills":[{"skill":"Fly","value":4},{"skill":"Perception","value":5},{"skill":"Survival","value":1,"special":"+5 to keep from getting lost"}],"environments":["temperate forests","temperate plains"],"organizations":["solitary","buzz (2-5)","hive (11-20)"],"treasure":"none","description_visual":"This is a giant-sized bumblebee, much larger than its normal sized counterpart.","group":"Bumblebee","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fortitude DC 14; frequency; 1/round for 6 rounds; effect 1d2 Con; cure 1 save. The save DC is Constitution-based."}],"description":"Giant bumblebees generally behave like their much smaller relatives, building underground nests and burrows. Workers collect nectar and pollen and build or repair the burrow while the queen creates a brood chamber where she lays her eggs. The queen lays her eggs over the entire summer months. In late summer and early autumn, the eggs hatch, forming new drones and queens. Both drones and queens leave the nest to mate with other bumblebees. A giant bumblebee is about 8 ft. long with a black body striped with yellow bands. Giant bumblebees are generally passive creatures. If threatened however, or if their nest is disturbed, they respond by stinging their opponents.","ecology":"","habitat_society":""},{"name":"Giant Chameleon","cr":3,"xp":800,"alignment":"N","size":"Large","type":"animal","init":2,"senses":[{"type":"all-around vision"},{"type":"low-light vision"},{"type":"scent"},{"type":"superior vision"}],"ac":14,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+2 Dex, +3 natural, -1 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":6,"will":2,"defensive_abilities":["all-around vision"],"immunities":["flanks"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"bite +5 (1d8+4 plus grab)","ranged":"tongue +5 (1d3+3 plus grab)","space":"10 ft.","reach":"5 ft. (10 ft. with tongue)","special_attacks":[{"type":"swallow whole","details":"1d4 acid damage, AC 11, 10 hp"}],"strength":17,"dexterity":15,"constitution":17,"intelligence":2,"wisdom":12,"charisma":2,"baseatk":3,"cmb":7,"cmb_special":"+4 vs. grapple","cmd":19,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (tongue)"}],"skills":[{"skill":"Climb","value":15},{"skill":"Perception","value":17},{"skill":"Stealth","value":17}],"environments":["warm forests"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This giant lizard has a pebbly hide and eyes that protrude from the sides of its head such that they appear to be capable of independent movement.","group":"Chameleon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"All-Around Vision","kind":"Ex","details":"A giant chameleon can rotate each eye, independently of the other, in an 180 degree radius. This gives it a +4 racial bonus on Perception checks, and it cannot be flanked."},{"type":"Superior Vision","kind":"Ex","details":"By magnifying an image, a giant chameleon can see five times as far as a normal human. This grants the chameleon a +4 racial bonus on Perception checks. This bonus stacks with all-around vision."}],"description":"Giant chameleons are highly territorial creatures, and rarely is more than one is encountered in the same area, except during mating season when both a male and female may be encountered. Giant chameleons are omnivorous, preferring to feed on giant insects such as flies, larva, crickets, grasshoppers, rodents, and lizards. They hunt during the daylight hours, spending the early morning hours sunning themselves on rocks or mounds of leaves and grass. Giant chameleons reproduce up to three times per year. The female lays a clutch of 1d10+8 eggs and buries them in shallow earth or soil. Six months later, the young emerge into the world. Young giant chameleons reach maturity in a few months and leave the lair. Giant chameleons are either green or brown in color with the females being slightly darker and heavier than the males. Males are distinguished by the white lateral line running the length of their bodies and the dark bands extending from head to tail. Females usually possess a dark yellow lateral stripe. Both species have striped throats and lips. Giant chameleons sit completely still watching for potential prey to come within range of their tongue. Once a creature is located, the giant chameleon shoots its tongue out, grabs the prey, and reels it into its mouth, where it is chewed and swallowed. Giant Horned Chameleon The giant horned chameleon is a territorial creature and is rarely encountered with another of its kind except during mating season. Giant horned chameleons are green or dark green. Males are distinguished by the three large horns protruding from their head. This grants them a gore attack (1d8 + Strength modifier) that they can use in lieu of a bite or tongue attack. Females possess the same horns, but they are usually underdeveloped (dealing 1d6 + Strength modifier). These chameleons have a crest on the back of their head, and bony ridges and spines running the length of their back. Rock Chameleon Rock chameleons resemble common giant chameleons but their natural coloration is gray and they are only found in warm and temperate mountains where their coloration allows them to blend in with their surroundings. They use the stats for the common giant chameleon, but only gain the bonus to Stealth checks in rocky surroundings.","ecology":"","habitat_society":""},{"name":"Giant Dire Frog","cr":3,"xp":800,"alignment":"N","size":"Large","type":"animal","init":6,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":19,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+2 Dex, +8 natural, -1 size","hp":50,"hd":"4d8+28","hdvalue":4,"fort":11,"ref":8,"will":2,"speed":[{"type":"land","speed":40},{"type":"swim","speed":40}],"melee":"bite +8 (1d8+6 plus grab) or tongue +8 touch (grab)","space":"10 ft.","reach":"10 ft. (20 ft. with tongue)","special_attacks":[{"type":"pull","details":"tongue, 10 ft."},{"type":"swallow whole","details":"1d8+6 bludgeoning damage, AC 12, 2 hp"},{"type":"tongue"}],"strength":23,"dexterity":15,"constitution":24,"intelligence":1,"wisdom":12,"charisma":10,"baseatk":3,"cmb":10,"cmb_special":"+4 vs. grapple","cmd":22,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Acrobatics","value":11,"special":"+15 jumping"},{"skill":"Perception","value":6},{"skill":"Stealth","value":2},{"skill":"Swim","value":14}],"environments":["temperate aquatic","temperate marshes","warm aquatic","warm marshes"],"organizations":["solitary","pair","army (3-8)"],"treasure":"none","description_visual":"This frog appears to be at least 10 ft. long. It resembles a feral amphibian with dark mottled skin and black splotches on its body.","group":"Frog","source":"Tome of Horrors Complete (3pp)","description":"Giant frogs leap into combat using their charge attack. Though giant frogs (the smallest variety) may flee or not attack opponents larger than themselves, the larger variety (dire, killer, and Abyssal) are ferocious and nearly mindless killing machines, attacking everything in sight that isn't a frog.","ecology":"","habitat_society":""},{"name":"Giant Hamster","cr":3,"xp":800,"alignment":"N","size":"Large","type":"animal","init":1,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+1 Dex, +5 natural, -1 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":5,"will":2,"immunities":["disease"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":10}],"melee":"bite +6 (1d8+6 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"cheek pouch"}],"strength":19,"dexterity":13,"constitution":16,"intelligence":1,"wisdom":12,"charisma":6,"baseatk":3,"cmb":8,"cmb_special":"+4 vs. grapple","cmd":19,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Climb","value":9},{"skill":"Perception","value":9}],"environments":["temperate hills"],"organizations":["small pack (1d4 adults plus 10% chance of 1d4 young)"],"treasure":"none","description_visual":"What should be a tiny, cuddly creature is instead a behemoth of tan fur and over-sized teeth. Its eyes gleam with a feral intensity.","group":"Hamster","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Cheek Pouch","kind":"Ex","details":"A giant hamster can try to stuff a grabbed opponent of two sizes smaller than itself into its cheek pouch by making a successful grapple check. A creature stuffed into the giant hamster's cheek pouch takes no damage, and can escape by making a successful DC 16 Strength check or can cut its way out by using a light slashing or piercing weapon to deal 10 points of damage to the cheek (AC 11). Once the creature exits, muscular action closes the hole; another trapped opponent must cut its own way out. A Large hamster's cheek can hold 1 Small, 2 Tiny, or 8 Diminutive or smaller opponents. The check DC is Strength-based."},{"type":"Immune","kind":"Ex","details":"Giant hamsters are immune to all diseases (magical and otherwise)."}],"description":"Giant hamsters are larger, slightly more aggressive relatives of the normal hamster. Like their smaller cousins, they come in a variety of colors, shapes, and sizes. Giant hamsters are omnivorous, but prefer to feast on a diet of grains, berries, nuts, and water. On occasion, they indulge in and eat meat, usually insects and the like. Also like its smaller cousin, the giant hamster can store food in its cheek pouches. The average giant hamster can store about 200 pounds of food at any given time.\n\nGiant hamsters normally shun combat, but if cornered or extremely hungry they may attack. Note that even domesticated giant hamsters attack if their young are threatened. The giant hamster attacks by biting with its long, sharp teeth.","ecology":"","habitat_society":"","credit":"The Giant Hamster originally appeared in the Second Edition Monstrous Compendium (MC 7) (© TSR/Wizards of the Coast, 1990) and is used by permission."},{"name":"Giant Horsefly","cr":3,"xp":800,"alignment":"N","size":"Large","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":15,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+2 Dex, +4 natural, -1 size","hp":26,"hd":"4d8+8","hdvalue":4,"fort":6,"ref":3,"will":2,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"bite +6 (1d6+6 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain","details":"1d4 Constitution"}],"strength":18,"dexterity":15,"constitution":14,"wisdom":12,"charisma":7,"baseatk":3,"cmb":8,"cmb_special":"+4 vs. grapple","cmd":20,"skills":[{"skill":"Fly","value":4},{"skill":"Perception","value":5}],"environments":["temperate forests","temperate marshes","warm forests","warm marshes"],"organizations":["solitary","pair","nest (10-20)"],"treasure":"none","description_visual":"This creature looks like an 8-foot long hairy, black fly.","group":"Horsefly","source":"Tome of Horrors Complete (3pp)","description":"Giant horseflies are aggressive relatives of the smaller horsefly and generally frequent the same type of habitat. Their lairs are always built near a source of water and the lair itself is kept damp by water from the surrounding ground. A typical nest contains one female and up to 20 males. One male is taken as a mate and during the spring or fall months, the female lays a clutch of 5-8 eggs. During warmer months or when the temperature is extremely high, a flurry of activity can be noticed around the nest as the horseflies prepare for the colder months and the female prepares to lay her eggs. Young hatch within a few weeks and resemble giant larvae with segmented bodies. Each segment of the larvae's body has small protuberances that aid in movement.\n\nGiant horseflies sustain themselves on a diet of nectar, pollen, and blood.\n\nTheir hunting territory typically covers a range of several square miles around their nest. Blooded targets usually involve animals, livestock, and the occasional humanoid.\n\nGiant horseflies look like large, black hairy flies. Their bodies are thick and their multifaceted eyes are black and dark gold. Wings are translucent and their legs are long, bristly and jet black. Females have a slightly longer mouth tube than males.\n\nGiant horseflies attack by delivering a painful bite to their opponent. If hunting, a giant horsefly attempts to grapple its foe and drain its blood.\n\nSlain prey is left to rot; the giant horsefly only drinks its blood, it doesn't eat its remains.","ecology":"","habitat_society":""},{"name":"Giant Rock-horned Lizard","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"animal","init":2,"senses":[{"type":"low-light vision"}],"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 Dex, +6 natural","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":6,"will":2,"speed":[{"type":"land","speed":30},{"type":"swim","speed":20}],"melee":"bite +8 (1d6+6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"spit blood","details":"20 ft. line, 2d8 acid, Reflex DC 15 half, usable every hour"}],"strength":18,"dexterity":14,"constitution":17,"intelligence":2,"wisdom":12,"charisma":2,"baseatk":3,"cmb":7,"cmd":19,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Climb","value":12},{"skill":"Perception","value":8},{"skill":"Stealth","value":10,"special":"+14 in forests and undergrowth"},{"skill":"Swim","value":16}],"environments":["warm forests"],"organizations":["solitary"],"treasure":"none","description_visual":"This giant reddish-brown lizard has small horns protruding form its wedge-shaped head.","group":"Lizard","source":"Tome of Horrors Complete (3pp)","description":"The rock-horned lizard is commonly referred to as the blood lizard because of its ability to shoot a stream of blood from its eyes when threatened. The rock-horned lizard grows to a length of eight ft. Its head is wedge-shaped, and small horns protrude from the sides and top of its head. Its scales are dark reddish-brown or gold in color. The rock-horned lizard fires a stream of blood from the corners of its eyes at its foes before rushing in to attack with its bite.","ecology":"","habitat_society":""}];
